public class GradeBookTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        GradeBook book = new GradeBook();
        check("averageGrade of an empty book", 0.0, book.averageGrade());
        check("honorRoll of an empty book", "[]", book.honorRoll(60).toString());
        book.add(new Student("Dana", 88));
        book.add(new Student("Alice", 90));
        book.add(new Student("Bob", 74));
        Student alice = book.lookup("Alice");
        check("lookup finds Alice's grade", 90, alice == null ? null : alice.getGrade());
        check("lookup of a missing name", null, book.lookup("Zed"));
        check("averageGrade of three students", 84.0, book.averageGrade());
        check("honorRoll(85) sorted alphabetically", "[Alice, Dana]", book.honorRoll(85).toString());
        check("honorRoll(60) includes everyone, sorted", "[Alice, Bob, Dana]", book.honorRoll(60).toString());
        book.add(new Student("Bob", 95));
        Student bob = book.lookup("Bob");
        check("re-adding a name replaces the entry", 95, bob == null ? null : bob.getGrade());
        check("averageGrade after the replacement", 91.0, book.averageGrade());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
